using System;
using System.IO;
using System.Linq;
using System.Collections.Generic;
using System.Windows;
using System.Windows.Controls;
internal static class UnifiedLibraryTests {
 static void Check(bool value,string message){if(!value)throw new Exception(message);}
 static QuestInstruction Entry(string guide,int order,string text,string coordinates="0,0",string id="10"){return new QuestInstruction{GuideSlug=guide,GuideTitle=guide,QuestName="Première quête fictive",GameQuestId=id,Key=guide+"/"+order,Order=order,Details=text,Coordinates=coordinates,Credit=guide,Url="https://ganymede-app.com/guides/1?page="+order};}
 internal static void Run(string folder){
 var index=new QuestInstructionIndex();index.Items.AddRange(new[]{Entry("ganymede-1",1,"A"),Entry("ganymede-1",2,"C"),Entry("ganymede-2",1,"A"),Entry("ganymede-2",2,"B"),Entry("ganymede-2",3,"C"),Entry("ganymede-3",1,"WRONG ID","0,0","99")});var step=new TougliStep{Title="Premiere quete fictive",QuestId="10",Key="test"};var merged=index.Merge(step);Check(String.Join("",merged.Items.Select(x=>x.Details))=="ABC"&&!merged.ConflictingOrder,"Exact name matching, ID veto, deduplication or shared-anchor order failed");Check(merged.References[merged.Items[0].Key].Count==2,"Deduplication lost source references");Check(Object.ReferenceEquals(merged,index.Merge(step)),"Repeated merge recomputed");Check(index.Merge(new TougliStep{Title="Premiere quete fictiv",QuestId="10"}).Items.Count==0,"Approximate name matched");
 var repeated=UnifiedQuestInstructions.Build(new List<QuestInstruction>{Entry("ganymede-1",1,"A"),Entry("ganymede-1",2,"B"),Entry("ganymede-1",3,"A"),Entry("ganymede-2",1,"A"),Entry("ganymede-2",2,"B"),Entry("ganymede-2",3,"A")});Check(String.Join("",repeated.Items.Select(x=>x.Details))=="ABA"&&!repeated.ConflictingOrder,"Return visit lost by deduplication");
 var conflict=UnifiedQuestInstructions.Build(new List<QuestInstruction>{Entry("ganymede-1",1,"A"),Entry("ganymede-1",2,"B"),Entry("ganymede-2",1,"B"),Entry("ganymede-2",2,"A")});Check(conflict.ConflictingOrder&&conflict.Items.Count==2,"Contradictory order hidden or instructions lost");
 var positions=UnifiedQuestInstructions.Build(new List<QuestInstruction>{Entry("ganymede-1",1,"A","1,2"),Entry("ganymede-2",1,"A","3,4")});Check(positions.Items.Count==2,"Different coordinates silently collapsed");
 var store=new Store(Path.Combine(folder,"unified-library"));var c=new DofusCharacter{id="unified",name="Unifié",guide="parcours-exemple",classCode="Sacri"};store.Value.dofus.characters.Add(c);store.Value.dofus.active=c.id;store.Value.instructions.cursors[QuestInstructionIndex.CursorKey(store.Value,step,"ganymede-2")]=index.Items[3].Key;string cursor=QuestInstructionIndex.CursorKey(store.Value,step,"unified");Check(merged.Position(store.Value,step,cursor)==1,"Legacy instruction cursor not recovered");
 var guides=Enumerable.Range(0,60).Select(i=>new TougliGuideInfo{Slug="parcours-"+i,Title="Parcours "+i,Category="Test"}).ToList();guides.Add(new TougliGuideInfo{Slug="ganymede-1",Title="Hidden reference"});GuideLibrary.Merge(store,guides);store.Save();var visible=GuideLibrary.Parcours(store);Check(guides.Where(g=>!GanymedeReader.IsGuide(g.Slug)).All(g=>visible.Any(v=>v.Slug==g.Slug))&&visible.All(g=>!GanymedeReader.IsGuide(g.Slug)),"Tougli catalogue missing guides or exposes reference catalogues");
 var window=new CompanionWindow(store,true);var library=window.OptionsPreview(true);CompanionWindow.RenderPreview(library,Path.Combine(folder,"unified-library.png"));var grid=StandaloneTests.Find<ListBox>(library.Content as DependencyObject).Single(x=>x.Items.Count>0&&x.Items[0] is GuideChoice);Check(grid.Items.Count==24&&!StandaloneTests.Find<ComboBox>(library.Content as DependencyObject).Any(),"Icon grid not paginated or source dropdown remains");var first=grid.Items.Cast<GuideChoice>().Select(g=>g.Slug).ToArray();StandaloneTests.Find<Button>(library.Content as DependencyObject).First(b=>Equals(b.Content,"Page →")).RaiseEvent(new RoutedEventArgs(Button.ClickEvent));Check(!grid.Items.Cast<GuideChoice>().Any(g=>first.Contains(g.Slug)),"Second icon page repeats first page");var search=StandaloneTests.Find<TextBox>(library.Content as DependencyObject).First(x=>x.MaxLength==180);search.Text="Parcours 59";Check(grid.Items.Count==1&&((GuideChoice)grid.Items[0]).Slug=="parcours-59","Search does not cover all pages");library.Close();window.Close();
 File.WriteAllText(Path.Combine(folder,"UNIFIED_LIBRARY_PASS.txt"),"PASS: exact normalized names; known ID conflicts excluded; deduplicated references; shared-anchor chronological order; repeated visits preserved; conflicting orders flagged; differing coordinates retained; legacy cursor recovery; all 60 synthetic Tougli guides retained; reference catalogues hidden; actual icon grid, pagination and search across pages; no source dropdown.");
 }
}
